-- Gangasagar database: all migrations, then the seed.
-- Generated by `npm run db:combine` from supabase/migrations and supabase/seed.sql. Do not edit by hand.
-- Run it once, on a new Supabase project, in the SQL editor.

-- ==== 20261107000100_core.sql ====

-- Core: admin allowlist, profiles, site settings.


-- Admin allowlist (emails, lower case). Never exposed to the API roles.
create table public.admins (
  email text primary key check (email = lower(email))
);
alter table public.admins enable row level security;
revoke all on public.admins from anon, authenticated;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  -- Admins must have signed up with Google: an email/password sign-up using an admin's
  -- address (possible if someone turns off email confirmation) never becomes an admin.
  select coalesce(auth.jwt()->'app_metadata'->>'provider', '') = 'google'
     and exists (
    select 1 from public.admins a
    where a.email = lower(coalesce(auth.jwt()->>'email', ''))
  )
$$;
revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated, service_role;

-- Profiles, one per signed-in user.
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text,
  phone text,
  whatsapp text,
  promo_opt_in boolean not null default false,
  created_at timestamptz not null default now()
);
alter table public.profiles enable row level security;
revoke all on public.profiles from anon, authenticated;
grant select on public.profiles to authenticated;
grant update (full_name, phone, whatsapp, promo_opt_in) on public.profiles to authenticated;

create policy profiles_select_own on public.profiles
  for select to authenticated
  using (id = auth.uid() or public.is_admin());

create policy profiles_update_own on public.profiles
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.profiles (id, full_name)
  values (new.id, nullif(trim(new.raw_user_meta_data->>'full_name'), ''))
  on conflict (id) do nothing;
  return new;
end;
$$;
revoke all on function public.handle_new_user() from public, anon, authenticated;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Site settings: public key/value configuration. Everyone reads, admins write.
create table public.site_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.site_settings enable row level security;
revoke all on public.site_settings from anon, authenticated;
grant select on public.site_settings to anon, authenticated;
grant insert, update, delete on public.site_settings to authenticated;

create policy site_settings_read on public.site_settings
  for select to anon, authenticated
  using (true);

create policy site_settings_admin_insert on public.site_settings
  for insert to authenticated
  with check (public.is_admin());

create policy site_settings_admin_update on public.site_settings
  for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

create policy site_settings_admin_delete on public.site_settings
  for delete to authenticated
  using (public.is_admin());

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger site_settings_touch
  before update on public.site_settings
  for each row execute function public.touch_updated_at();

-- ==== 20261107000200_catalog.sql ====

-- Catalogue: categories, products, variants (with private stock), stock movements.

create table public.categories (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  parent_id uuid references public.categories (id) on delete set null,
  name_en text not null,
  name_hi text,
  image_url text,
  sort integer not null default 0,
  is_active boolean not null default true
);

create table public.products (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  category_id uuid references public.categories (id) on delete set null,
  brand text,
  name_en text not null,
  name_hi text,
  description_en text,
  description_hi text,
  images text[] not null default '{}',
  seo_title_en text,
  seo_title_hi text,
  seo_description_en text,
  seo_description_hi text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index products_category_idx on public.products (category_id);

create trigger products_touch
  before update on public.products
  for each row execute function public.touch_updated_at();

-- Loose variants: retail_price is per kg, net_weight_g = 1000, stock_unit = 'kg'.
create table public.variants (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  label_en text not null,
  label_hi text,
  net_weight_g integer not null check (net_weight_g > 0),
  pack_type text,
  retail_price numeric(10,2) not null check (retail_price > 0),
  mrp numeric(10,2) check (mrp is null or mrp > 0),
  sale_price numeric(10,2) check (sale_price is null or (sale_price > 0 and sale_price < retail_price)),
  sale_ends_at timestamptz,
  is_loose boolean not null default false,
  loose_min_g integer,
  loose_step_g integer,
  stock_qty numeric(12,3) not null default 0 check (stock_qty >= 0),
  stock_unit text not null default 'packs' check (stock_unit in ('packs', 'kg')),
  min_stock numeric(12,3),
  limited_below numeric(12,3),
  is_active boolean not null default true,
  sort integer not null default 0,
  constraint variants_loose_shape check (
    not is_loose or (
      net_weight_g = 1000 and stock_unit = 'kg'
      and loose_step_g > 0 and loose_min_g >= loose_step_g and loose_min_g % loose_step_g = 0
    )
  ),
  constraint variants_pack_shape check (is_loose or stock_unit = 'packs')
);
create index variants_product_idx on public.variants (product_id);

create table public.stock_movements (
  id uuid primary key default gen_random_uuid(),
  variant_id uuid not null references public.variants (id) on delete restrict,
  kind text not null check (kind in ('incoming','sale','damaged','expired','adjustment','cancellation_return')),
  qty numeric(12,3) not null,
  note text,
  order_id uuid,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);
create index stock_movements_variant_idx on public.stock_movements (variant_id, created_at desc);

-- Row-level security and grants.
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.variants enable row level security;
alter table public.stock_movements enable row level security;

revoke all on public.categories, public.products, public.variants, public.stock_movements from anon, authenticated;
grant select on public.categories, public.products to anon, authenticated;
grant insert, update, delete on public.categories, public.products to authenticated;
grant select, insert, update, delete on public.variants to authenticated;
grant select on public.stock_movements to authenticated;

create policy categories_read on public.categories for select to anon, authenticated
